import{_t as e,it as t,n,rt as r}from"./chunks/framework.BhEEDjPG.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"run/environment.md","filePath":"run/environment.md"}`),a={name:`run/environment.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><p>Unset = the safe default. Every hardening feature is opt-in; every write flag must equal the literal string <code>&quot;true&quot;</code>; stores fall back with a warning rather than failing boot.</p><h2 id="model-chain-llm" tabindex="-1">Model chain (<code>LLM_*</code>) <a class="header-anchor" href="#model-chain-llm" aria-label="Permalink to “Model chain (LLM_*)”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th></tr></thead><tbody><tr><td><code>LLM_CHAIN</code></td><td>Ordered endpoint names, e.g. <code>openai,anthropic</code>, <code>ollama</code>, <code>mock</code>. Unset ⇒ legacy single provider (<code>ANTHROPIC_API_KEY</code> / <code>LLM_API_BASE</code>+<code>LLM_MODEL</code>) or the mock.</td></tr><tr><td><code>LLM_&lt;NAME&gt;_PRESET</code></td><td>Reuse a preset under another name (two models of one provider). Presets: anthropic, mock, openai, ollama, vllm, llamacpp, lmstudio, fireworks, together, deepseek, gemini, groq, mistral, openrouter.</td></tr><tr><td><code>LLM_&lt;NAME&gt;_BASE</code> / <code>_MODEL</code> / <code>_API_KEY</code></td><td>The endpoint. Local bases need no key.</td></tr><tr><td><code>LLM_&lt;NAME&gt;_TEMPERATURE</code></td><td>number or <code>none</code> (omit the field).</td></tr><tr><td><code>LLM_&lt;NAME&gt;_REASONING_EFFORT</code></td><td><code>low</code>/<code>medium</code>/<code>high</code>/<code>none</code>/<code>omit</code>.</td></tr><tr><td><code>LLM_&lt;NAME&gt;_BODY</code></td><td>JSON merged into every request (<code>null</code> removes a preset field).</td></tr><tr><td><code>LLM_&lt;NAME&gt;_PRICE</code></td><td><code>input,cached,output[,cache_write]</code> USD per million.</td></tr><tr><td><code>LLM_&lt;NAME&gt;_NOTES</code></td><td>Per-model notes file (<code>none</code> to disable); default <code>shared-skills/model-notes/&lt;slug&gt;.md</code>.</td></tr><tr><td><code>LLM_&lt;NAME&gt;_AUTH_HEADER</code></td><td>Send the key in this header instead of <code>Authorization: Bearer</code>.</td></tr><tr><td><code>LLM_FAILOVER_THRESHOLD</code> (2), <code>LLM_FAILOVER_COOLDOWN_S</code> (60), <code>LLM_RETRIES</code> (2), <code>LLM_RETRY_MAX_WAIT_MS</code> (20000), <code>LLM_TIMEOUT_MS</code> (120000)</td><td>Breaker and retries.</td></tr><tr><td><code>ANTHROPIC_API_KEY</code>, <code>ANTHROPIC_MODEL</code></td><td>The anthropic preset.</td></tr><tr><td><code>AGENT_ROUTER_MODEL</code>, <code>AGENT_ROUTER_MIN_CONFIDENCE</code> (0.35)</td><td>Routing hop.</td></tr></tbody></table><h2 id="typed-decisions-verdict" tabindex="-1">Typed decisions (<code>VERDICT_*</code>) <a class="header-anchor" href="#typed-decisions-verdict" aria-label="Permalink to “Typed decisions (VERDICT_*)”">​</a></h2><p><code>VERDICT_SYSTEMONE_URL</code>, <code>VERDICT_SYSTEMONE_MODEL</code> (laya), <code>VERDICT_SYSTEMONE_API_KEY</code>, <code>VERDICT_MIN_CONFIDENCE</code> (0.6), <code>VERDICT_ESCALATE_BELOW</code> (0.5), <code>VERDICT_LLM</code> (<code>off</code> disables the LLM link).</p><h2 id="safety-and-identity-agent" tabindex="-1">Safety and identity (<code>AGENT_*</code>) <a class="header-anchor" href="#safety-and-identity-agent" aria-label="Permalink to “Safety and identity (AGENT_*)”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>AGENT_ALLOW_WRITES</code></td><td>unset (off)</td><td>Real writes only when literally <code>true</code>.</td></tr><tr><td><code>AGENT_REQUIRE_LOGIN</code></td><td>on</td><td><code>false</code> only for dev/evals/probe.</td></tr><tr><td><code>AGENT_AUTH_VERIFY_URL</code></td><td>—</td><td>Strict identity verification endpoint (GET with the bearer).</td></tr><tr><td><code>AGENT_TOKEN_SECRET</code>, <code>AGENT_TOKEN_TTL_S</code> (900), <code>AGENT_APP_KEYS</code> (<code>key:tenant,…</code>)</td><td>—</td><td>The agent-token exchange.</td></tr><tr><td><code>AGENT_ENTITLEMENT_URL</code>, <code>AGENT_ENTITLEMENT_KEY</code></td><td>—</td><td>Seats and caps at exchange.</td></tr><tr><td><code>AGENT_GATEWAY_KEYS</code>, <code>AGENT_ADMIN_KEY</code>, <code>AGENT_CORS_ORIGINS</code>, <code>AGENT_TRUST_PROXY</code>, <code>AGENT_MAX_MESSAGE_CHARS</code> (4000), <code>AGENT_LINK_SCHEMES</code></td><td>—</td><td>Gateway hardening.</td></tr><tr><td><code>AGENT_GUARDS</code></td><td>on</td><td><code>false</code> disables the runtime guards (raw-model evals only).</td></tr><tr><td><code>AGENT_TYPED_PROMPT</code></td><td>on</td><td><code>false</code> loads every type&#39;s skill and tools.</td></tr></tbody></table><h2 id="limits-and-cost" tabindex="-1">Limits and cost <a class="header-anchor" href="#limits-and-cost" aria-label="Permalink to “Limits and cost”">​</a></h2><p><code>AGENT_RATE_SESSIONS_PER_IP</code> (20), <code>AGENT_RATE_CHAT_PER_SESSION</code> (10), <code>AGENT_RATE_CHAT_PER_IP</code> (60), <code>AGENT_RATE_TRANSCRIBE_PER_IP</code> (30), <code>AGENT_RATE_MEDIA_PER_IP</code> (60), <code>AGENT_RATE_MAX_CONCURRENT</code> (8), <code>AGENT_RATE_DISABLED</code>; <code>AGENT_CAP_TOKENS_PER_SESSION</code>, <code>_5H</code>, <code>_DAY</code>, <code>_WEEK</code>, <code>_MONTH</code>, <code>AGENT_CAP_CONTEXT_TOKENS</code>, <code>AGENT_CAP_TZ_OFFSET_MIN</code>; <code>AGENT_PLAN_WEIGHT_INPUT/CACHED/OUTPUT/CACHE_WRITE</code>; <code>AGENT_TOOL_RESULT_MAX_CHARS</code> (12000), <code>AGENT_TOOL_RESULT_KEEP_CHARS</code> (1500), <code>AGENT_TRIM_TOOL_HISTORY_TURNS</code> (2); <code>AGENT_MAX_TOOL_ROUNDS</code> (10); <code>AGENT_MAX_HISTORY_MESSAGES</code> (60); <code>AGENT_SESSION_CACHE</code> (2000).</p><h2 id="stores-sessions-retention" tabindex="-1">Stores, sessions, retention <a class="header-anchor" href="#stores-sessions-retention" aria-label="Permalink to “Stores, sessions, retention”">​</a></h2><p><code>AGENT_REDIS_URL</code>, <code>AGENT_MONGO_URL</code>, <code>AGENT_MONGO_DB</code> (marg), <code>AGENT_SESSION_DIR</code> (.sessions), <code>AGENT_SESSION_RETENTION_DAYS</code>, <code>AGENT_LEDGER_DIR</code> (.data/ledger).</p><h2 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to “Channels”">​</a></h2><p><code>DEEPGRAM_API_KEY</code> or <code>AGENT_STT_PROVIDER=openai</code> + <code>AGENT_STT_BASE</code> + <code>AGENT_STT_API_KEY</code>, <code>AGENT_STT_MODEL</code>, <code>AGENT_STT_LANGUAGE</code>, <code>AGENT_STT_KEYWORDS</code>, <code>AGENT_STT_PRICE_PER_MIN</code>; <code>AGENT_MEDIA_DOMAIN</code>, <code>AGENT_FILE_BASE</code>, <code>AGENT_MEDIA_MAX_IMAGE_MB</code> (15), <code>_FILE_MB</code> (25), <code>_VIDEO_MB</code> (128), <code>AGENT_MEDIA_MAX_ITEMS</code> (30); <code>AGENT_ENTITY_DEEPLINK</code>, <code>AGENT_UPLOAD_DEEPLINK</code> (<code>{entity_id}</code> templates); <code>AGENT_NUDGE_ENABLED</code>, <code>AGENT_NUDGE_MAX</code> (3), <code>AGENT_NUDGE_INTERVAL_MS</code> (300000), <code>AGENT_NUDGE_LINES</code>.</p><h2 id="observability-and-logs" tabindex="-1">Observability and logs <a class="header-anchor" href="#observability-and-logs" aria-label="Permalink to “Observability and logs”">​</a></h2><p><code>AGENT_O2_URL</code>, <code>AGENT_O2_ORG</code> (default), <code>AGENT_O2_USER</code>, <code>AGENT_O2_PASSWORD</code> or <code>AGENT_O2_TOKEN</code>, <code>AGENT_O2_LOG_STREAM</code>, <code>AGENT_O2_LOGS</code> (<code>off</code>), <code>OTEL_EXPORTER_OTLP_ENDPOINT</code>, <code>OTEL_EXPORTER_OTLP_HEADERS</code>, <code>OTEL_SERVICE_NAME</code>, <code>OTEL_TRACES_SAMPLER_ARG</code>, <code>AGENT_OTEL</code> (<code>off</code>), <code>AGENT_OTEL_CAPTURE_CONTENT</code> (heads), <code>AGENT_OTEL_METRICS_INTERVAL_MS</code> (15000); <code>LOG_LEVEL</code>, <code>AGENT_TRACE</code> (<code>off</code>), <code>AGENT_LOG_DIR</code>, <code>AGENT_LOG_RETENTION_DAYS</code> (14), <code>AGENT_LOG_STDOUT</code>, <code>AGENT_LOG_SYNC</code>, <code>AGENT_LOG_TO_STDERR</code>, <code>AGENT_REDACT_KEYS</code>, <code>AGENT_REDACT_PHONES</code>; <code>AGENT_ALERT_ERROR_RATIO</code> (0.5), <code>AGENT_ALERT_WEBHOOK</code>.</p><h2 id="metering" tabindex="-1">Metering <a class="header-anchor" href="#metering" aria-label="Permalink to “Metering”">​</a></h2><p><code>AGENT_METERING_URL</code>, <code>AGENT_METERING_API_KEY</code>, <code>AGENT_METERING_PRODUCT</code> (agent).</p><h2 id="process" tabindex="-1">Process <a class="header-anchor" href="#process" aria-label="Permalink to “Process”">​</a></h2><p><code>GATEWAY_PORT</code> (8787), <code>AGENT_BRAND</code> (Marg), <code>AGENT_SERVICE_NAMESPACE</code> (marg), <code>AGENT_METRIC_PREFIX</code> (agent), <code>AGENT_ENV</code> (local), <code>AGENT_DOMAIN_DIRS</code> (domains,examples), <code>AGENT_DOMAINS</code> (all), <code>AGENT_PUBLIC_DIR</code>, <code>AGENT_WIDGET_FILE</code>, <code>AGENT_SHARED_SKILLS_DIR</code>, <code>AGENT_REPO_ROOT</code>, <code>AGENT_SHUTDOWN_GRACE_MS</code> (10000). <code>AGENT_REPO_ROOT</code> defaults to the repository root when running from a checkout and to the working directory&#39;s project (the nearest <code>package.json</code> or <code>.git</code>) when the packages are installed from npm; <code>.env</code>, <code>domains/</code>, <code>examples/</code> and <code>shared-skills/</code> are read from there.</p><h2 id="evals" tabindex="-1">Evals <a class="header-anchor" href="#evals" aria-label="Permalink to “Evals”">​</a></h2><p><code>EVAL_GATEWAY</code> (<a href="http://localhost:8788" target="_blank" rel="noreferrer">http://localhost:8788</a>), <code>SCENARIO</code>, <code>EVAL_SHARD</code> (<code>i/n</code>), <code>EVAL_RERUNS</code>, <code>EVAL_FLAKES</code>, <code>EVAL_VERBOSE</code>, <code>EVAL_BEARER</code>.</p><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/ENVIRONMENT.md">docs/ENVIRONMENT.md</a> — edit it there; the site mirrors the repository.</small></p>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};